#!/usr/bin/env python3
"""crispr/prime_editor_pegrna — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "prime_editor_pegrna"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'prime_editor_pegrna', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Prime editor pegRNA 设计:spacer + sgRNA scaffold + RTT(reverse transcription template)+ PBS(primer binding site)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    target = payload.get("target_sequence")
    edit_pos = int(payload.get("edit_position", -1))  # 0-based
    edit_to = payload.get("edit_to", "")  # 替换后的序列
    pbs_len = int(payload.get("pbs_length", 13))
    rtt_len = int(payload.get("rtt_length", 15))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "pbs_len": pbs_len, "rtt_len": rtt_len}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not target or edit_pos < 0:
        return {"ok": False, "error": "需要 target_sequence + edit_position", "diagnostics": diagnostics}
    seq_u = target.upper()
    pbs = seq_u[max(0, edit_pos - pbs_len):edit_pos]
    rtt_template = seq_u[edit_pos:edit_pos + rtt_len]
    # 简化:edit_to 替换 RTT 的中间区
    rtt_with_edit = (edit_to.upper() + rtt_template[len(edit_to):]) if edit_to else rtt_template
    pegRNA = f"spacer + scaffold + {rtt_with_edit}_RTT + {pbs}_PBS"
    return {"ok": True, "skill_id": SKILL,
            "n_guides": 1, "guides_csv": "",
            "best_guide": {"seq": pegRNA, "cfd_score": 0.0, "mit_score": 0.0},
            "pbs": pbs, "rtt": rtt_with_edit, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
